import { extractEmojis } from 'unicode-emoji-utils';

/*
important note: emoji replacement
- if we are to correctly encode emojis, we should run emojiEncode first, then htmlEncode
- this way emojis send through as &#<hexcode> and not as &amp;#<hexcode>
- engine currently doesn't play ball with emojis encoded as &#<hexcode>
- so for a user, sending &#<hexcode> will convert to an emoji character
*/
export function encodeChatMessage(message: string, enableEmojis: boolean, isOld: boolean = false): string {
    return htmlEncode(emojiEncode(message, isOld, enableEmojis));
}

export function decodeChatMessage(message: string): string {
    return emojiDecode(htmlDecode(message));
}

function cleanHrefs(value: string): string {
    return value.replace(/href="(.*)"/gi, (substring) => {
        return substring.replace(/(?:javascript:|data:|vbscript:)/gi, '');
    });
}

function htmlDecode(value: string): string {
    return cleanHrefs(value
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'")
        .replace(/&apos;/g, "'")
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&amp;/g, '&')
    );
}

function htmlEncode(value: string): string {
    return value
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function emojiEncode(msg: string, isOld: boolean, enableEmojis: boolean = true) {
    const base = isOld ? 10 : 16; // Use base 10 for old messages, base 16 for new ones
    const pad = isOld ? 0 : 6; // Use character pad length of 0 for old messages, 6 for new ones
    const endCharacter = isOld ? ';' : ''; // Use semicolon for old messages, none for new ones
    return Array.from(msg).map(char => {
        const isZeroWidthJoiner = char.length === 1 && char.codePointAt(0) === 8205; // Zero Width Joiner
        if (isZeroWidthJoiner) {
            return enableEmojis ? `&#${(8205).toString(base).padStart(pad, '0')}${endCharacter}` : '';
        }
        if (char.length > 1 || extractEmojis(char).length > 0) {
            const codePoint = char.codePointAt(0);
            if (codePoint !== undefined) {
                return enableEmojis ? `&#${codePoint.toString(base).padStart(pad, '0')}${endCharacter}` : '';
            }
        }
        return char;
    }).join('');
}

function emojiDecode(message: string) {
    return message
        .replace(/&#([0-9]{1,8});/gi, // start off replacing the base 10 for old messages
            (_, baseTen) => {
                try {
                    const codePoint = parseInt(baseTen, 10);
                    return String.fromCodePoint(codePoint);
                } catch (e) {
                    return '';
                }
            })
        .replace(/&#x([a-fA-F0-9]{1,6});/gi, // start off replacing the base 10 for old messages
            (_, italyHex) => {
                try {
                    const codePoint = parseInt(italyHex, 16);
                    return String.fromCodePoint(codePoint);
                } catch (e) {
                    return '';
                }
            })
        .replace(/&#([a-fA-F0-9]{6})/gi, //run the base 16 check after for new messages
            (_, hexCode) => {
                try {
                    const codePoint = parseInt(hexCode, 16);
                    return String.fromCodePoint(codePoint);
                } catch (e) {
                    if (e instanceof RangeError) {
                        return `&#${hexCode}`;
                    }
                    return '';
                }
            });
}